      "name": "Polynomial.taylor_C",
      "module_name": "Mathlib.Algebra.Polynomial.Taylor",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (r x : R), (Polynomial.taylor r) (Polynomial.C x) = Polynomial.C x"
    },
    {
      "name": "Polynomial.taylor_one",
      "module_name": "Mathlib.Algebra.Polynomial.Taylor",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (r : R), (Polynomial.taylor r) 1 = Polynomial.C 1"
    },
    {
      "name": "Polynomial.taylor_zero",
      "module_name": "Mathlib.Algebra.Polynomial.Taylor",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (f : Polynomial R), (Polynomial.taylor 0) f = f"
    },
    {
      "name": "Polynomial.taylor",
      "module_name": "Mathlib.Algebra.Polynomial.Taylor",
      "kind": "definition",
      "type": "{R : Type u_1} → [inst : Semiring R] → R → Polynomial R →ₗ[R] Polynomial R"
    },
    {
      "name": "MvPolynomial.C_apply",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} {a : R} [inst : CommSemiring R], MvPolynomial.C a = (MvPolynomial.monomial 0) a"
    }
  ]
}

