    {
      "name": "MvPolynomial.aeval_map_algebraMap",
      "module_name": "Mathlib.RingTheory.MvPolynomial.Tower",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} (A : Type u_2) {B : Type u_3} {σ : Type u_4} [inst : CommSemiring R] [inst_1 : CommSemiring A]\n  [inst_2 : CommSemiring B] [inst_3 : Algebra R A] [inst_4 : Algebra A B] [inst_5 : Algebra R B] [IsScalarTower R A B]\n  (x : σ → B) (p : MvPolynomial σ R),\n  (MvPolynomial.aeval x) ((MvPolynomial.map (algebraMap R A)) p) = (MvPolynomial.aeval x) p"
    },
    {
      "name": "Polynomial.aeval_map_algebraMap",
      "module_name": "Mathlib.RingTheory.Polynomial.Tower",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} (A : Type u_2) {B : Type u_3} [inst : CommSemiring R] [inst_1 : CommSemiring A] [inst_2 : Semiring B]\n  [inst_3 : Algebra R A] [inst_4 : Algebra A B] [inst_5 : Algebra R B] [IsScalarTower R A B] (x : B) (p : Polynomial R),\n  (Polynomial.aeval x) (Polynomial.map (algebraMap R A) p) = (Polynomial.aeval x) p"
    },
    {
      "name": "MvPolynomial.aeval",
      "module_name": "Mathlib.Algebra.MvPolynomial.Eval",
      "kind": "definition",
      "type": "{R : Type u} →\n  {S₁ : Type v} →\n    {σ : Type u_1} →\n      [inst : CommSemiring R] →\n        [inst_1 : CommSemiring S₁] → [inst_2 : Algebra R S₁] → (σ → S₁) → MvPolynomial σ R →ₐ[R] S₁"
    },
    {
      "name": "MvPolynomial.eval₂_C",
      "module_name": "Mathlib.Algebra.MvPolynomial.Eval",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S₁ : Type v} {σ : Type u_1} [inst : CommSemiring R] [inst_1 : CommSemiring S₁] (f : R →+* S₁)\n  (g : σ → S₁) (a : R), MvPolynomial.eval₂ f g (MvPolynomial.C a) = f a"
    },
    {
      "name": "MvPolynomial.eval₂Hom_C_left",
      "module_name": "Mathlib.Algebra.MvPolynomial.Monad",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {τ : Type u_2} {R : Type u_3} [inst : CommSemiring R] (f : σ → MvPolynomial τ R),\n  MvPolynomial.eval₂Hom MvPolynomial.C f = ↑(MvPolynomial.bind₁ f)"
    }
  ]
}

{
  "items": [
    {
      "name": "Algebra.Generators.Hom.toAlgHom_C",
      "module_name": "Mathlib.RingTheory.Extension.Generators",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S : Type v} {ι : Type w} [inst : CommRing R] [inst_1 : CommRing S] [inst_2 : Algebra R S]\n  {P : Algebra.Generators R S ι} {R' : Type u_1} {S' : Type u_2} {ι' : Type u_3} [inst_3 : CommRing R']\n  [inst_4 : CommRing S'] [inst_5 : Algebra R' S'] {P' : Algebra.Generators R' S' ι'} [inst_6 : Algebra R R']\n  [inst_7 : Algebra S S'] (f : P.Hom P') (r : R), f.toAlgHom (MvPolynomial.C r) = MvPolynomial.C ((algebraMap R R') r)"
    },
    {
      "name": "Polynomial.mapAlg_eq_map",
      "module_name": "Mathlib.Algebra.Polynomial.AlgebraMap",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommSemiring R] (S : Type v) [inst_1 : Semiring S] [inst_2 : Algebra R S] (p : Polynomial R),\n  (Polynomial.mapAlg R S) p = Polynomial.map (algebraMap R S) p"
    },
    {
      "name": "MvPolynomial.algHom_C",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] {A : Type u_2} [inst_1 : Semiring A] [inst_2 : Algebra R A]\n  (f : MvPolynomial σ R →ₐ[R] A) (r : R), f (MvPolynomial.C r) = (algebraMap R A) r"
    },
    {
      "name": "MvPolynomial.algebraMap_apply",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S₁ : Type v} {σ : Type u_1} [inst : CommSemiring R] [inst_1 : CommSemiring S₁] [inst_2 : Algebra R S₁]\n  (r : R), (algebraMap R (MvPolynomial σ S₁)) r = MvPolynomial.C ((algebraMap R S₁) r)"
    },
    {
      "name": "Polynomial.CAlgHom",
      "module_name": "Mathlib.Algebra.Polynomial.AlgebraMap",
      "kind": "definition",
      "type": "{R : Type u} →\n  {A : Type z} → [inst : CommSemiring R] → [inst_1 : Semiring A] → [inst_2 : Algebra R A] → A →ₐ[R] Polynomial A"
    }
  ]
}

