      "module": "Mathlib.RingTheory.MvPolynomial.Tower"
    },
    {
      "name": "IsLocalization.Away.mvPolynomialQuotientEquiv_apply",
      "type": " {R : Type u_2} [CommRing R] (S : Type u_3) [CommRing S] [Algebra R S] (r : R) [IsLocalization.Away r S] (p : MvPolynomial Unit R) : (IsLocalization.Away.mvPolynomialQuotientEquiv S r) ((Ideal.Quotient.mk (Ideal.span {MvPolynomial.C r * MvPolynomial.X () - 1})) p) = (MvPolynomial.aeval fun x => IsLocalization.Away.invSelf r) p",
      "module": "Mathlib.RingTheory.MvPolynomial.Localization"
    },
