      "type": " {R : Type u} {S : Type v} {ι : Type w} {σ : Type t} [CommRing R] [CommRing S] [Algebra R S] {ι' : Type u_1} {σ' : Type u_2} {T : Type u_3} [CommRing T] [Algebra S T] (Q : Algebra.Presentation S T ι' σ') (P : Algebra.Presentation R S ι σ) [Algebra R T] [IsScalarTower R S T] (r : σ') : (MvPolynomial.aeval (Sum.elim MvPolynomial.X (⇑MvPolynomial.C ∘ P.val))) ((Q.comp P).relation (Sum.inl r)) = Q.relation r",
