      "name": "MvPolynomial.universalFactorizationMapPresentation_relation",
      "type": " (R : Type u_1) [CommRing R] (n m k : ℕ) (hn : n = m + k) (i : Fin n) : (MvPolynomial.universalFactorizationMapPresentation R n m k hn).relation i = MvPolynomial.C (MvPolynomial.X i) - (MvPolynomial.map MvPolynomial.C) ((MvPolynomial.tensorEquivSum R (Fin m) (Fin k) R) ((MvPolynomial.universalFactorizationMap R n m k hn) (MvPolynomial.X i)))",
      "module": "Mathlib.RingTheory.Polynomial.UniversalFactorizationRing"
    }
  ]
